var npcId=2071000, maps=[222000000], entries=[[3610, 0, "消灭鬼怪的准备", ["看来你是从外地来的年轻人啊。别看我这么一把年纪，看人的眼光还是有的，我看你好像蛮强的嘛.. 可以听听我说的话吗？听说不久前，赫丽奥斯塔图书馆发生了大问题。虽然不清楚是怎么回事，那个时候从童话书中逃出来的鬼怪们藏在村子后面的乌山里了。", "自从鬼怪们逃进乌山之后，乌山里一直持续着黑夜，大概是鬼怪们弄出来的。统领乌山鬼怪的是三只鬼怪王，唯有消灭这些鬼怪，乌山才会恢复以前的样子。怎么样，你可以完成这个事情吗？"], "童话村的朴大爷请求我消灭村庄后山上的鬼怪。在乌山出现的鬼怪是从鬼怪故事书里逃出来的，藏身在山中的一所凶宅里。若想让藏的很隐密的鬼怪们现出原形，就需要有鬼怪喜欢的三种诱饵。要在村庄找出#b#t2022050#, #t2022051#, #t2022052##k，再回去找朴大爷。\n\n#t2022050#  #b#c2022050##k / 1\n#t2022051#  #b#c2022051##k / 1\n#t2022052#  #b#c2022052##k / 1", ["看来我看人的眼光还是很准的嘛，我就知道你会答应我的请求的。消灭那些鬼怪可不是一件容易的事情，那些鬼怪藏的很隐密，不会让人们轻易发现。想要把它们引出来，就需要用它们喜欢的诱饵。", "据说怪物们喜欢#b#t2022050##k和 #b#t2022051#, #t2022052##k，这些可以在村民那里得到，把这些都得到后拿来给我"], {}, []], [3610, 1, "消灭鬼怪的准备", ["都找来了，你还真不简单。我们村子里的人们本来是不太愿意帮助外地人的，看来你确实是有些特殊的地方。"], "童话村的朴大爷请求我消灭村庄后山上的鬼怪。在乌山出现的鬼怪是从鬼怪故事书里逃出来的，藏身在山中的一所凶宅里。若想让藏的很隐密的鬼怪们现出原形，就需要有鬼怪喜欢的三种诱饵。要在村庄找出#b#t2022050#, #t2022051#, #t2022052##k，再回去找朴大爷。\n\n#t2022050#  #b#c2022050##k / 1\n#t2022051#  #b#c2022051##k / 1\n#t2022052#  #b#c2022052##k / 1", [], {}, []], [3611, 0, "消灭鬼怪", ["现在，拿着那些到乌山山顶上。那里的凶宅里藏着童话书里逃出来的三只鬼怪王，他们轻易是不会被人们发现的，藏的很隐密。最后再问你一次，真的有自信办到这件事情吗？可能会比想象中要难一些。"], "拿着鬼怪喜欢的三样食品，开始正式消灭鬼怪的工作。朴大爷说到山中的凶宅附近放下诱饵就能引出鬼怪，并详细告诉我要放置诱饵的地方。猪肉串要放在石堆前面，荞麦蒟蒻要放在树洞里，谷茶要放在石灯里，是这样没错吧？\n\n#o7130400# #r#a36113##k\n#o7130401# #r#a36111#", ["看你自信满满的，呵呵.. 那么，现在开始告诉你引出鬼怪的方法。#b黄色鬼怪王#k非常胆小，被榛子咬破的声音吓得扔掉鬼怪棒跑掉的正是这个鬼怪。这个鬼怪喜欢吃猪肉。在凶宅附近的#b石堆#k前放下#b猪肉串#k，牠就会出现的。", "下一个是#b蓝色鬼怪王#k，这只鬼怪有严重的健忘症。总会丢三落四的，听说连鬼怪帽都被丢掉过，曾经有人捡到了那东西而进行偷窃被人们发现过。这个鬼怪喜欢#b谷茶#k，在凶宅附近的#b石灯#k里放进谷茶，牠就会出现的。", "最后一个是#b绿色鬼怪王#k，它特别喜欢摔角。有时会在三更半夜出现在人们面前缠着他们摔角，把人给累趴之后逃之夭夭。这个鬼怪喜欢#b荞麦蒟蒻#k，在凶宅附近的#b树洞#k里放进#b荞麦蒟蒻#k，牠就会出现的。", "消灭这3只鬼怪王，把它们掉下的鬼怪棍棒、鬼怪的帽子、鬼怪披风拿来。那就拜托你了，你一个人的话可能会有些吃力，借助朋友的力量去完成也可以的。"], {}, []], [3611, 1, "消灭鬼怪", ["真了不起！了不起！竟然真的打败了3只鬼怪王啊！！多亏了你，可以把那些鬼怪送回童话书里了。为了表示对你的谢意，送给你一件鬼怪身上掉出的物品，挑一个吧。"], "拿着鬼怪喜欢的三样食品，开始正式消灭鬼怪的工作。朴大爷说到山中的凶宅附近放下诱饵就能引出鬼怪，并详细告诉我要放置诱饵的地方。猪肉串要放在石堆前面，荞麦蒟蒻要放在树洞里，谷茶要放在石灯里，是这样没错吧？\n\n#o7130400# #r#a36113##k\n#o7130401# #r#a36111#", ["想要那件东西吗？把'鬼怪的故事'童话书拿给图书馆的图书管理员先生吧，他可能正在寻找这些书呢。"], {}, [[1002483, 1], [1322033, 1], [1102064, 1]]], [3628, 0, "鬼怪故事童话书", ["呵呵，年轻人，旅途愉快吗？听说最近你在帮助图书管理员威兹？真是善良的年轻人啊，今天来找我是为什么事？", "把我送给你的童话书弄丢了？该好好保管才对啊。不过不用担心，我这里还有那童话书。给你之前，希望你能答应我的一个请求，可以吗？如果是你的话应该很容易办到的。"], "赫丽奥斯塔图书馆的管理员威兹托我为他带来#b#t4031238##k。以前消灭鬼怪王之后有得到过这样东西，可是现在却找不到了。找到朴大爷说明了情况后，他说只要拿给他#b#t4000173# 10个#k，就能得到童话书。\n\n#t4000173# #b#c4000173##k/10", ["多亏你消灭了三只鬼怪王，帮了我们很大的忙，不过乌山上还有很多鬼怪住着。那些鬼怪特别爱捣蛋，所以让人们很头疼。那就拜托你去消灭那些鬼怪，带来#b#t4000173# 10个#k吧，对你来说应该是非常简单的事情吧？"], {}, []], [3628, 1, "鬼怪故事童话书", ["拿来了吗？让我来看看。10把扫帚没错，收下这本童话书吧，这次可要好好保管了啊。"], "赫丽奥斯塔图书馆的管理员威兹托我为他带来#b#t4031238##k。以前消灭鬼怪王之后有得到过这样东西，可是现在却找不到了。找到朴大爷说明了情况后，他说只要拿给他#b#t4000173# 10个#k，就能得到童话书。\n\n#t4000173# #b#c4000173##k/10", ["既然有了扫帚，那就和村民来一次大扫除啊？最近来这里的外地人越来越多，一直想做一次大扫除。辛苦你啦。"], {}, []], [3635, 0, "狩猎狐狸", ["呼~ 真让人担心啊，因为那些狐狸，村民们都生了病，唉... \r\n#L0##b发生了什么事？#k", "唉，别提了。你是外地人有所不知，村子后面的乌山住着叫做#r#o5100004##k的狐狸，最近因为那些狐狸，让我们非常苦恼。\r\n#L0##b到底是什么苦恼请说一下吧，如果可以的话我愿意帮助你们。#k", "真的吗？"], "童话村的长老#b#p2071000##k正因住在乌山的#r#o5100004##k向村民施加诅咒，导致村民中生病的人不断增多而非常担心。为了解开施加在村民身上的诅咒，需要#b狐狸尾巴 999个#k，而每只#t4000172#身上会有#b3个#k狐狸尾巴，快去弄来#b#t4000172# 333个#k吧。\n\n#t4000172#  #b#c4000172##k / 333", ["住在乌山的那些狐狸叫做#r#o5100004##k，是还没有变成九尾狐的狐狸。虽然还很小，但是它们的法术和调皮捣蛋的程度丝毫不比九尾狐差呢。最近那些#o5100004#经常对路过的村民们施加诅咒，结果大家都生病了。", "当然还不至于让人们死掉，但大家都这样病恹恹的，不能出去工作，只能躺在家里不能起来啊。据说，要解开#o5100004#的诅咒需要#b狐狸尾巴 999个#k。", "#o5100004#有3个尾巴，所以只要有#b#t4000172# 333个#k就能解开#o5100004#的诅咒了。希望你能完成这件事情，如果是你的话应该能充分对付#o5100004#的。\n\n#i4000172#  #t4000172# #b333#k个\n\n#o5100004#在#b狐狸坡#k附近就能找到。"], {"0": {"options": [0], "correct": 0, "wrong": []}, "1": {"options": [0], "correct": 0, "wrong": []}}, []], [3635, 1, "狩猎狐狸", ["怎么样了？弄到狐狸尾巴了吗？哎呀，看你浑身是伤啊。你手上那些不就是#b#t4000172##k吗！终于还是办到了，只要有了这些，村民身上的诅咒就能都化解了。"], "童话村的长老#b#p2071000##k正因住在乌山的#r#o5100004##k向村民施加诅咒，导致村民中生病的人不断增多而非常担心。为了解开施加在村民身上的诅咒，需要#b狐狸尾巴 999个#k，而每只#t4000172#身上会有#b3个#k狐狸尾巴，快去弄来#b#t4000172# 333个#k吧。\n\n#t4000172#  #b#c4000172##k / 333", ["能够从狐狸坡安然无恙的回来，真是够神奇的。而且还能把我拜托你的#t4000172#都弄来，你可真是个了不起的人啊。今后也请您时常来我们村帮助我们吧。"], {}, []]], greeting="呵呵~欢迎来到我们村庄~";
var choices=[], picked=null, page=0, stage="menu", closed=false, started=false, origin=-1, rewardIndex=-1;
function finish(){closed=true;cm.dispose();}
function validPlace(){
    return cm.getNpc()==npcId && maps.indexOf(cm.getMapId())>=0 && (origin<0 || origin==cm.getMapId());
}
function ready(){
    var q=Packages.server.quest.MapleQuest.getInstance(picked[0]);
    return picked[1]==0 ? q.canStart(cm.getPlayer(),cm.getNpc()) : q.canComplete(cm.getPlayer(),cm.getNpc());
}
function start(){
    if(closed || started)return;
    started=true;
    if(!validPlace()){finish();return;}
    origin=cm.getMapId();
    var menu="";
    for(var i=0;i<entries.length;i++){
        var d=entries[i],q=Packages.server.quest.MapleQuest.getInstance(d[0]);
        if((d[1]==0 && q.canStart(cm.getPlayer(),cm.getNpc())) || (d[1]==1 && cm.getQuestStatus(d[0])==1)){
            menu+="\r\n#L"+choices.length+"#"+(d[1]==0?"[接受] ":"[继续] ")+d[2]+"#l";
            choices.push(d);
        }
    }
    if(choices.length==0){cm.sendOk(greeting+"\r\n\r\n当前没有可以交接的普通任务。");finish();return;}
    cm.sendSimple(greeting+"\r\n"+menu);
}
function showBefore(){
    var text=picked[3][page];
    if(picked[6][String(page)])cm.sendSimple(text);
    else if(page==picked[3].length-1)cm.sendYesNo(text);
    else cm.sendNext(text);
}
function commit(){
    if(!ready()){cm.sendOk(picked[4] || "任务条件尚未完成，请查看任务栏中的要求。");finish();return;}
    if(picked[7].length>0 && rewardIndex<0){
        stage="reward";
        var menu="请选择一件任务奖励：";
        for(var i=0;i<picked[7].length;i++)menu+="\r\n#L"+i+"##i"+picked[7][i][0]+"# #t"+picked[7][i][0]+"# × "+picked[7][i][1]+"#l";
        cm.sendSimple(menu);return;
    }
    closed=true;
    if(picked[7].length>0){
        // Native reward selection is zero based; client rewards here have no job/gender filters.
        var q=Packages.server.quest.MapleQuest.getInstance(picked[0]);
        var player=cm.getPlayer(),npc=cm.getNpc(),client=cm.getClient();
        cm.dispose();client.removeClickedNPC();
        q.complete(player,npc,java.lang.Integer.valueOf(rewardIndex),false);
    }else if(picked[1]==0)cm.startClientNpcQuest(picked[0]);
    else cm.completeClientNpcQuest(picked[0]);
}
function accepted(){
    if(picked[5].length==0){commit();return;}
    stage="after";page=0;cm.sendNext(picked[5][page]);
}
function action(mode,type,selection){
    if(closed)return;
    if(!validPlace() || mode!=1){finish();return;}
    if(stage=="menu"){
        if(selection<0 || selection>=choices.length || selection!=Math.floor(selection)){finish();return;}
        picked=choices[selection];
        if(!ready()){cm.sendOk(picked[4] || "任务条件尚未完成，请查看任务栏中的要求。");finish();return;}
        stage="before";page=0;showBefore();return;
    }
    if(stage=="before"){
        var answer=picked[6][String(page)];
        if(answer){
            if(answer.options.indexOf(selection)<0){finish();return;}
            if(selection!=answer.correct){
                if(answer.wrong.length>0)cm.sendOk(answer.wrong.join("\r\n"));
                finish();return;
            }
        }
        if(page<picked[3].length-1){page++;showBefore();return;}
        if(answer){stage="confirm";cm.sendYesNo(picked[2]);return;}
        accepted();return;
    }
    if(stage=="confirm"){accepted();return;}
    if(stage=="reward"){
        if(selection<0 || selection>=picked[7].length || selection!=Math.floor(selection)){finish();return;}
        rewardIndex=selection;commit();return;
    }
    if(stage=="after"){
        if(page<picked[5].length-1){page++;cm.sendNext(picked[5][page]);return;}
        commit();
    }
}

entries.push([8572, 1, "\u4fee\u70bc\u91d1\u4e39\u7684\u6750\u6599", ["\u4f60\u662f\u8c01\uff1f\u6211\u53ea\u8ba4\u8bc6#b#p9330015##k."], "\u6750\u6599\u5f88\u96be\u627e\u53ef\u662f\uff0c\u53ea\u62ff\u53bb\u6750\u6599\u662f\u6ca1\u7528\u7684\uff0c\u5fc5\u987b\u8fd8\u8981\u53d8\u8eab\u3002\u3002\u3002\n\n#t4010001# #b#c4010001##k/2\n\n#t4010000# #b#c4010000##k/2\n\n#t4000018# #b#c4000018##k/10\n\n#t4000005# #b#c4000005##k/10\n\n#t2022000# #b#c2022000##k/2\n\n#t4000155# #b#c4000155##k/30\n", ["\u4f60\u4e0d\u662f#b#p9330015##k\uff0c\u8ba9#b#p9330015##k\u6765\u627e\u6211\u3002"], {}, []]);
entries.push([8574, 0, "\u89e3\u6551\u5c48\u539f", ["#b#p9330015##k\u662f\u4f60\u5417\uff1f\u771f\u53ef\u60dc\u4f60\u7684\u6028\u6c14\u592a\u5927\u65e0\u6cd5\u6295\u80ce\u8f6c\u4e16\u3002\u3002\u3002\u4ec0\u4e48\uff1f\u4f60\u600e\u4e48\u77e5\u9053\u6211\u53ef\u4ee5\u5236\u4f5c#b#t4031952##k\uff1f"], "\u53ea\u6709\u4fee\u70bc\u91d1\u4e39\u624d\u80fd\u89e3\u6551\u5c48\u539f\u7684\u7075\u9b42\u3002", ["\u4f60\u8fde\u6750\u6599\u90fd\u6536\u96c6\u597d\u4e86\uff1f\u5475\u5475~\u90a3\u597d\u5427\uff0c\u6211\u5c31\u5e2e\u4f60\u5427\uff01"], {}, []]);
